mapper.select:
select CREDIT_TAG_ID , CREDIT_TAG_NAME , RISK_RATIO , CREDIT_USING_TYPE , CREDIT_TYPE , DEDUCT_RULE , IS_PERPETUAL_SEC , ISSUE_TYPE , IS_FX , CUR_PAIR , TERM_VALUE ,TERM_UNIT from CREDIT_TAG_INFO t
AND t.CREDIT_TYPE in
#{item}
AND t.CREDIT_TAG_ID in
#{item}
AND t.DEDUCT_RULE = #{deductRule}
AND t.CREDIT_TAG_NAME IS NOT NULL
order by t.UPDATE_TIME desc

	SELECT
		CREDIT_TAG_ID id,
		CREDIT_TAG_NAME text
	FROM
		CREDIT_TAG_INFO

        /*add by yushilong 去除非法人标签显示 20200703 start*/
        CREDIT_TYPE != '13'
        /*add by yushilong 去除非法人标签显示 20200703 end*/

            AND CREDIT_TAG_ID = #{initValue, jdbcType=VARCHAR}


            AND CREDIT_TAG_NAME LIKE CONCAT('%', CONCAT(#{search}, '%'))

		SELECT count(1)
		FROM CREDIT_TAG_INFO A


                  AND  CREDIT_TAG_NAME =#{tagName,jdbcType=VARCHAR}


                  AND  CREDIT_TAG_ID !=#{tagId,jdbcType=VARCHAR}

select count(1) from sys_datadict_list t
t.DICT_CODE = 'LIMIT_TYPE'
AND item_value =#{tagName,jdbcType=VARCHAR}
